def transform(grid):
    h = len(grid)
    w = len(grid[0])
    result = [row[:] for row in grid]

    # Find source column (mixed values)
    source_c = -1
    for c in range(w):
        vals = set(grid[r][c] for r in range(h))
        if len(vals) > 1:
            source_c = c
            break

    # Find feature column (uniform non-bg, neighbor of source)
    bg = grid[0][0]
    feature_c = -1
    for dc in [1, -1]:
        c = source_c + dc
        if 0 <= c < w:
            vals = set(grid[r][c] for r in range(h))
            if len(vals) == 1 and grid[0][c] != bg:
                feature_c = c
                break

    # Get reversed pattern from source column
    pattern = [grid[r][source_c] for r in range(h)][::-1]

    # Determine first column to fill (preserving source and feature)
    min_c = -1
    for c in range(w):
        if c != source_c and c != feature_c:
            min_c = c
            break

    # Fill all non-preserved columns with pattern
    if min_c != -1:
        for c in range(w):
            if c == source_c or c == feature_c:
                continue
            idx = (c - min_c) % h
            for r in range(h):
                result[r][c] = pattern[idx]

    return result
